package com.gathin.tvhome;
import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.os.*;
import android.text.InputType;
import android.widget.*;
import java.util.*;

/** Local family UX. PIN never enters profile exports, AI drafts or the general settings file. */
final class FamilyMode {
    private static final String FILE="freedom_family_private",PIN="parent_pin",GUARD="guard_opt_in";
    private static long editUntil;private static String approvedTarget="";private static long targetUntil;
    static SharedPreferences privatePrefs(Context c){return c.getSharedPreferences(FILE,0);}
    static FamilyPolicy spec(Context c){try{return new FamilyPolicy(ProfileStore.preferences(c).getString(FamilyPolicy.KEY,""));}catch(RuntimeException bad){return new FamilyPolicy("");}}
    static boolean pin(Context c){return !privatePrefs(c).getString(PIN,"").isEmpty();}
    static boolean active(Context c){return pin(c)&&privatePrefs(c).getStringSet("approved-profiles",Collections.emptySet()).contains(ProfileStore.id())&&spec(c).enabled;}
    static boolean allowed(Context c,String pkg){return !active(c)||spec(c).allowed.contains(pkg);}
    static boolean editing(Context c){return !active(c)||SystemClock.elapsedRealtime()<editUntil;}
    static boolean guard(Context c){return active(c)&&privatePrefs(c).getBoolean(GUARD,false);}
    static boolean canSelect(Context c,String target){return selectionAllowed(c,target,true);}
    static boolean selectionAllowed(Context c,String target,boolean consume){boolean restricted=false;try{restricted=new FamilyPolicy(ProfileSetup.global(c).getString(LocalProfiles.key(target,FamilyPolicy.KEY),"")).enabled&&pin(c)&&privatePrefs(c).getStringSet("approved-profiles",Collections.emptySet()).contains(target);}catch(RuntimeException ignored){}boolean approved=target.equals(approvedTarget)&&SystemClock.elapsedRealtime()<targetUntil;boolean ok=FamilyPolicy.canSelect(active(c),restricted,target.equals(ProfileStore.id()),approved);if(ok&&consume){approvedTarget="";targetUntil=0;}return ok;}
    static void select(Activity a,String target,Runnable action){if(selectionAllowed(a,target,false)){action.run();return;}authorize(a,()->{approvedTarget=target;targetUntil=SystemClock.elapsedRealtime()+20000;action.run();});}
    static void filter(Context c,List<String> dock,List<String> hidden,List<String> top){if(!active(c))return;Set<String> allowed=spec(c).allowed;dock.removeIf(p->!allowed.contains(p));top.removeIf(p->!allowed.contains(p));Set<String> blocked=new HashSet<>();for(String category:new String[]{Intent.CATEGORY_LEANBACK_LAUNCHER,Intent.CATEGORY_LAUNCHER})for(ResolveInfo app:c.getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(category),0))if(app.activityInfo!=null&&!allowed.contains(app.activityInfo.packageName))blocked.add(app.activityInfo.packageName);for(String p:blocked)if(!hidden.contains(p))hidden.add(p);}
    static EditText field(Activity a,String hint){EditText e=new EditText(a);e.setHint(hint);e.setSingleLine(true);e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);e.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(8)});e.setSaveEnabled(false);e.setImportantForAutofill(android.view.View.IMPORTANT_FOR_AUTOFILL_NO);return e;}
    static void authorize(Activity a,Runnable action){if(!pin(a)||SystemClock.elapsedRealtime()<editUntil){action.run();return;}SharedPreferences prefs=privatePrefs(a);if(System.currentTimeMillis()<prefs.getLong("retry-after",0)){Toast.makeText(a,"Please wait before another parent PIN attempt",Toast.LENGTH_LONG).show();return;}String before=prefs.getString(PIN,"");EditText input=field(a,"Parent PIN");AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Parent approval").setMessage("Approve this launcher action only. Android settings and ADB remain outside this convenience lock.").setView(input).setNegativeButton("Cancel",null).setPositiveButton("Approve",null).create();dialog.setOnShowListener(x->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String value=input.getText().toString();try{LockPolicy.validPin(value);}catch(Exception bad){input.setError("Use 4–8 digits");return;}dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(false);new Thread(()->{boolean verified=false;try{verified=LockPolicy.verify(before,value);}catch(Exception ignored){}boolean ok=verified;new Handler(Looper.getMainLooper()).post(()->{if(a.isDestroyed()||!dialog.isShowing())return;input.setText("");if(!before.equals(prefs.getString(PIN,""))){dialog.dismiss();return;}if(ok){prefs.edit().remove("failed").remove("retry-after").commit();dialog.dismiss();editUntil=SystemClock.elapsedRealtime()+300000;action.run();}else{int n=prefs.getInt("failed",0)+1;prefs.edit().putInt("failed",n).putLong("retry-after",System.currentTimeMillis()+(n>=5?30000:0)).commit();input.setError(n>=5?"Please wait 30 seconds":"Incorrect PIN");if(n<5)dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(true);}});},"Family PIN check").start();}));dialog.show();}
    static void setPin(Activity a){LinearLayout b=FreedomUi.body(a);EditText one=field(a,"New parent PIN"),two=field(a,"Repeat parent PIN");b.addView(one);b.addView(two);AlertDialog d=new AlertDialog.Builder(a).setTitle("Create parent PIN").setMessage("4–8 digits. Keep it yourself: this app cannot recover it. It is not included in backups. System settings, app-data changes and ADB can bypass this local lock.").setView(b).setNegativeButton("Cancel",null).setPositiveButton("Set PIN",null).create();d.setOnShowListener(x->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String value=one.getText().toString();try{LockPolicy.validPin(value);if(!value.equals(two.getText().toString()))throw new IllegalArgumentException("PINs do not match");}catch(Exception bad){two.setError(bad.getMessage());return;}d.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(false);new Thread(()->{String record=null;try{record=LockPolicy.create(value);}catch(Exception ignored){}String encoded=record;new Handler(Looper.getMainLooper()).post(()->{if(a.isDestroyed()||!d.isShowing())return;one.setText("");two.setText("");if(encoded!=null&&privatePrefs(a).edit().putString(PIN,encoded).commit()){d.dismiss();editUntil=SystemClock.elapsedRealtime()+300000;settings(a,true);}else{two.setError("Could not save PIN");d.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(true);}});},"Create family PIN").start();}));d.show();}
    static void settings(Activity a){if(!LauncherLock.require(a,()->settings(a)))return;authorize(a,()->settings(a,true));}
    static void settings(Activity a,boolean approved){if(!approved)return;if(!pin(a)){LinearLayout b=FreedomUi.body(a);b.addView(FreedomUi.text(a,"Family Homes",26));b.addView(FreedomUi.text(a,"Child-friendly Homes need a parent PIN first. This does not change streaming accounts, content ratings or Android settings.",17));AlertDialog d=new AlertDialog.Builder(a).setView(b).setNegativeButton(android.R.string.cancel,null).create();TextView create=FreedomUi.action(a,b,"Create parent PIN",()->{d.dismiss();setPin(a);});d.setOnShowListener(v->{if(d.getWindow()!=null)d.getWindow().setLayout(Math.min(FreedomUi.dp(a,720),a.getResources().getDisplayMetrics().widthPixels-FreedomUi.dp(a,64)),android.view.ViewGroup.LayoutParams.WRAP_CONTENT);create.post(()->{if(create.isInTouchMode())create.requestFocusFromTouch();else create.requestFocus();});});d.show();return;}FamilyPolicy before=spec(a);boolean[] enabled={before.enabled};LinkedHashSet<String> selected=new LinkedHashSet<>(before.allowed);String profile=ProfileStore.id();LinearLayout body=FreedomUi.body(a);body.addView(FreedomUi.text(a,"This profile only. Choose apps and Apply. Editing is approved for five minutes; Lock parent editing now when finished. This is a convenience boundary, not secure parental control.",17));TextView mode=FreedomUi.action(a,body,"Child-friendly Home · "+(enabled[0]?"On":"Off"),()->{});mode.setOnClickListener(v->{enabled[0]=!enabled[0];mode.setText("Child-friendly Home · "+(enabled[0]?"On":"Off"));});TextView apps=FreedomUi.action(a,body,"Allowed apps · "+selected.size(),()->{});apps.setOnClickListener(v->chooseApps(a,selected,()->apps.setText("Allowed apps · "+selected.size())));AlertDialog[] dialog={null};FreedomUi.action(a,body,"Apply to this profile",()->{try{if(!profile.equals(ProfileStore.id())||!editing(a))throw new IllegalArgumentException("Profile or approval changed");String raw=FamilyPolicy.encode(enabled[0],selected);Map<String,Object> change=new HashMap<>();change.put(FamilyPolicy.KEY,raw);ProductFeatures.beforeChange(a,"Change family Home");if(!SetupValues.commit(ProfileStore.preferences(a),change))throw new IllegalArgumentException("Could not save family Home");Set<String> approvedProfiles=new HashSet<>(privatePrefs(a).getStringSet("approved-profiles",Collections.emptySet()));if(enabled[0])approvedProfiles.add(profile);else approvedProfiles.remove(profile);if(!privatePrefs(a).edit().putStringSet("approved-profiles",approvedProfiles).commit())throw new IllegalArgumentException("Could not activate this profile");FamilyGuard.refresh(a);dialog[0].dismiss();a.recreate();}catch(IllegalArgumentException bad){Toast.makeText(a,bad.getMessage(),Toast.LENGTH_LONG).show();}});FreedomUi.action(a,body,"Optional app guard · "+(privatePrefs(a).getBoolean(GUARD,false)?"On":"Off"),()->guardSettings(a));FreedomUi.action(a,body,"Lock parent editing now",()->{editUntil=0;approvedTarget="";dialog[0].dismiss();});FreedomUi.action(a,body,"Change parent PIN",()->setPin(a));FreedomUi.action(a,body,"Remove parent PIN and restrictions",()->new AlertDialog.Builder(a).setTitle("Turn off family restrictions on this TV?").setMessage("Removes the parent PIN, local profile approvals and guard behaviour for all profiles. Saved apps/layouts remain. Accessibility access is a separate Android choice; disable the service there if no longer needed.").setPositiveButton("Remove and turn off",(d,n)->{if(privatePrefs(a).edit().clear().commit()){editUntil=0;approvedTarget="";FamilyGuard.refresh(a);dialog[0].dismiss();a.recreate();}}).setNegativeButton("Cancel",null).show());dialog[0]=FreedomUi.sheet(a,"Family Homes",body);}
    static void chooseApps(Activity a,LinkedHashSet<String> selected,Runnable changed){Map<String,String> apps=new TreeMap<>();for(String category:new String[]{Intent.CATEGORY_LEANBACK_LAUNCHER,Intent.CATEGORY_LAUNCHER})for(ResolveInfo r:a.getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(category),0))if(r.activityInfo!=null&&r.activityInfo.exported&&r.activityInfo.enabled&&!r.activityInfo.packageName.equals(a.getPackageName()))apps.put(r.activityInfo.packageName,String.valueOf(r.loadLabel(a.getPackageManager())));List<String> ids=new ArrayList<>(apps.keySet());String[] labels=new String[ids.size()];boolean[] checked=new boolean[ids.size()];for(int i=0;i<ids.size();i++){labels[i]=apps.get(ids.get(i));checked[i]=selected.contains(ids.get(i));}LinkedHashSet<String> draft=new LinkedHashSet<>(selected);new AlertDialog.Builder(a).setTitle("Allowed apps").setMultiChoiceItems(labels,checked,(d,n,on)->{if(on){if(draft.size()<128)draft.add(ids.get(n));else ((AlertDialog)d).getListView().setItemChecked(n,false);}else draft.remove(ids.get(n));}).setPositiveButton("Use this selection",(d,n)->{selected.clear();selected.addAll(draft);changed.run();}).setNegativeButton("Cancel",null).show();}
    static void guardSettings(Activity a){LinearLayout body=FreedomUi.body(a);body.addView(FreedomUi.text(a,"Optional Accessibility app guard watches only window package names while a child-friendly profile is active, and returns to DV Home for an unlisted app. It does not read screen contents or filter remote buttons. Android grants broader access; enable the service yourself. System settings, inputs, ADB and vendor windows can escape it.",17));FreedomUi.action(a,body,"Allow guard behaviour · explicit opt-in",()->{privatePrefs(a).edit().putBoolean(GUARD,true).commit();FamilyGuard.refresh(a);Toast.makeText(a,"Behaviour opted in; Accessibility access is still a separate system choice",Toast.LENGTH_LONG).show();});FreedomUi.action(a,body,"Turn guard behaviour off",()->{privatePrefs(a).edit().putBoolean(GUARD,false).commit();FamilyGuard.refresh(a);});FreedomUi.action(a,body,"Open Accessibility settings",()->{try{a.startActivity(new Intent(android.provider.Settings.ACTION_ACCESSIBILITY_SETTINGS));}catch(RuntimeException unavailable){Toast.makeText(a,"Open Accessibility in TV settings",Toast.LENGTH_LONG).show();}});FreedomUi.sheet(a,"Optional family app guard",body);}
    private FamilyMode(){}
}
